-- 018_v3_moat — outcomes, memories, corrections, draft_edits.
--
-- Reversible: yes — 018_v3_moat.down.sql
--
-- These are the unbackfillable signal tables. Every answer the system gives, every
-- correction the user makes, every draft the user edits — captured here. No competitor
-- can reconstruct this data because it is generated BY usage of the product.

create table if not exists outcomes (
  user_id      text not null references users(user_id) on delete cascade,
  outcome_id   text primary key,
  kind         text not null,
  person_id    text,
  suggested_at timestamptz not null default now(),
  payload      jsonb not null,
  result       text,
  result_at    timestamptz,
  they_replied boolean,
  meta         jsonb not null default '{}'
) partition by hash (user_id);

create table if not exists memories (
  user_id    text not null references users(user_id) on delete cascade,
  memory_id  text primary key,
  person_id  text,
  text       text not null,
  source     text not null,
  created_at timestamptz not null default now(),
  active     boolean not null default true
) partition by hash (user_id);

create table if not exists corrections (
  user_id       text not null references users(user_id) on delete cascade,
  correction_id text primary key,
  turn_id       text,
  claim         text not null,
  correction    text not null,
  created_at    timestamptz not null default now()
) partition by hash (user_id);

create table if not exists draft_edits (
  user_id    text not null references users(user_id) on delete cascade,
  edit_id    text primary key,
  person_id  text,
  drafted    text not null,
  sent       text,
  created_at timestamptz not null default now()
) partition by hash (user_id);

do $$
declare
  t text;
  i int;
begin
  foreach t in array array['outcomes', 'memories', 'corrections', 'draft_edits'] loop
    for i in 0..7 loop
      execute format(
        'create table if not exists %I partition of %I for values with (modulus 8, remainder %s)',
        t || '_p' || i, t, i
      );
    end loop;
  end loop;
end $$;
